package main

// ne_glyph_treemerged.go — MERGED TOPS, tile refresh and the note editor of the tree card
// (docs/ne-glyph.md row *TREE REPORTS*; observed-layer peer contract #same-tree, #tree-note,
// "Caching" under /trees/bbox).
//
// A reader says "same tree" on the extra top of a broad crown (ne_glyph_treerep.go trSame). The peer
// then drops that apex from the columns, adds its crown to its tree and lists it in `merged` — only
// when the tile has one. Here a merged top is an appended row with c.kd[i] = 5 and
// e.u[i].m = {n, ag, pi, plon, plat, px, py, cr}: n readers said same tree, ag said it is its own;
// pi = the row of its tree in this tile (−1 = another tile: plon/plat then come from the peer's
// EPSG:3035 of_x/of_y, trLL35). It is drawn as a dotted ring at its own crown with one hairline to
// its tree, never counted as a tree (apDraw), and has a card of its own (trMgCard): a two-way vote
// `same tree` / `its own tree`. Merged while n > ag — the peer's rule, applied locally at the answer
// (trMgAfter → trMgFlip) and then read back: every own flag re-reads the tile with a forced
// revalidation (trFresh, fetch cache:'no-cache') and swaps the rows in place under the pinned card
// (trReload). A tree report only re-reads to renew the browser's copy; no cache-buster parameter.

const neGlyphTreeMergedCSS = `
/* the note editor is one quiet box: the text, and inside the same hairline its footer — count on the left, cancel and save on the right. Nothing floats beside it, so the text has the row's whole width; the hairline darkens on focus, save wakes when there is something to save. A phone (below) only makes it roomier */.glyph-tip .tr .ne{display:flex;flex-direction:column;flex:1 1 100%;min-width:0;margin:.15em 0 .1em .4em;border:1px solid var(--rule);border-radius:5px;transition:border-color .15s;pointer-events:auto}.glyph-tip .tr .ne:focus-within{border-color:var(--fg)}
.glyph-tip .tr textarea{appearance:none;-webkit-appearance:none;display:block;background:transparent;border:0;border-radius:5px 5px 0 0;padding:.35em .55em 0;margin:0;min-width:0;width:100%;box-sizing:border-box;font:inherit;line-height:1.45;color:var(--fg);outline:none;pointer-events:auto;resize:none;overflow:auto}
.glyph-tip .tr .ne>.nb{display:flex;align-items:center;gap:0;padding:.2em .15em .2em .55em;font-size:var(--fz2);min-height:1.5em}/* with a keyboard at hand the footer is two glyphs: ↵ (save, wakes when there is something to save — Enter does the same) and × (Esc); remove lives on the saved note. A phone spells them out as buttons */.glyph-tip .tr .ne>.nb button{position:static;padding:0 .45em;background:none;border-color:transparent;color:var(--mut)}.glyph-tip .tr .ne>.nb button>i{font-style:normal}.glyph-tip .tr .ne>.nb button>b{display:none;font-weight:inherit}.glyph-tip .tr .ne>.nb button.rmv{display:none}.glyph-tip .tr .ne>.nb button.go{color:var(--fg)}.glyph-tip .tr .ne>.nb button:hover{color:var(--fg);background:color-mix(in srgb,var(--fg) 8%,transparent)}.glyph-tip .tr .ne>.nb button.go:disabled{color:var(--mut);opacity:.45;background:none}
.glyph-tip .tr textarea::placeholder{color:var(--mut);opacity:.8}
.glyph-tip .tr .rw.nr{align-items:flex-start}
.glyph-tip .tr .rw .vl>span.nb{display:flex;flex:1 1 100%;align-items:center;gap:.1em .2em;font-size:var(--fz2);min-height:1.5em}.glyph-tip .tr .nb .nc{margin-right:auto;font-variant-numeric:tabular-nums}.glyph-tip .tr .nb .sp{flex:1}
.glyph-tip .tr .rw .vl>span.nq{flex:1 1 100%;white-space:pre-line;overflow-wrap:anywhere;line-height:1.4;max-height:11em;overflow:auto;pointer-events:auto}.glyph-tip .tr .rw .vl>span.nq.cl{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.glyph-tip .tr button.mg i{font-style:normal;color:var(--mut);margin-left:.6em}
@media(hover:none) and (pointer:coarse){.glyph-tip .tr textarea{font-size:16px}}
/* a phone gives the note the card's whole width: the label goes above it, written or read */@media(max-width:640px),(hover:none) and (pointer:coarse){.glyph-tip .tr .rw.nr{flex-wrap:wrap}.glyph-tip .tr .rw.nr>.vl{flex:1 1 100%;min-width:0}.glyph-tip .tr .ne{margin:.15em 0;border-radius:8px}.glyph-tip .tr .ne textarea{border-radius:8px 8px 0 0;padding:.5em .65em 0}.glyph-tip .tr .ne>.nb{gap:.15em;padding:.4em .35em .45em .65em}.glyph-tip .tr .ne>.nb button{min-height:36px;min-width:4.2em;border-radius:999px;padding:0 .7em}.glyph-tip .tr .ne>.nb button>i{display:none}.glyph-tip .tr .ne>.nb button>b{display:inline}.glyph-tip .tr .ne>.nb button.rmv{display:inline-block}.glyph-tip .tr .ne>.nb button.go{order:9;margin-left:.2em;font-weight:600;color:var(--bg);background:var(--fg);border-color:var(--fg)}.glyph-tip .tr .ne>.nb button.go:disabled{background:transparent;color:var(--mut);border-color:var(--rule);opacity:.7}.glyph-tip .tr .rw.nr .vl>span.nb{margin-left:-.6em}}
`

